# Great! Pure Rust stdlib works. Let me check what OS-level syscalls I can access
# without the libc crate
cat > /tmp/test_rust/src/main.rs << 'EOF'
use std::fs::File;
use std::os::unix::io::AsRawFd;
use std::os::unix::fs::OpenOptionsExt;
use std::fs::OpenOptions;

// Test if we can call copy_file_range without the libc crate
fn copy_file_range(src: &File, dst: &File, len: usize) -> std::io::Result<usize> {
    use std::os::unix::io::RawFd;

    let result = unsafe {
        libc_copy_file_range(
            src.as_raw_fd(),
            std::ptr::null_mut(),
            dst.as_raw_fd(),
            std::ptr::null_mut(),
            len,
            0,
        )
    };

    if result < 0 {
        Err(std::io::Error::last_os_error())
    } else {
        Ok(result as usize)
    }
}

extern "C" {
    fn copy_file_range(
        fd_in: i32,
        off_in: *mut i64,
        fd_out: i32,
        off_out: *mut i64,
        len: usize,
        flags: u32,
    ) -> isize;
}

fn libc_copy_file_range(
    fd_in: i32,
    off_in: *mut i64,
    fd_out: i32,
    off_out: *mut i64,
    len: usize,
    flags: u32,
) -> isize {
    unsafe { copy_file_range(fd_in, off_in, fd_out, off_out, len, flags) }
}

fn main() {
    println!("test");
}
EOF
cd /tmp/test_rust && cargo build 2>&1

