cat > /tmp/test_rust/src/main.rs << 'EOF'
use std::fs::{File, OpenOptions};
use std::io::{self, Read, Write};
use std::os::unix::io::AsRawFd;

fn copy_file_range_syscall(src_fd: i32, dst_fd: i32, len: usize) -> io::Result<usize> {
    // Use Linux syscall number 326 on x86_64
    let result = unsafe {
        let res: isize;
        std::arch::asm!(
            "syscall",
            in("rax") 326i64, // copy_file_range syscall number
            in("rdi") src_fd as i64,
            in("rsi") 0i64, // off_in = NULL
            in("rdx") dst_fd as i64,
            in("r10") 0i64, // off_out = NULL
            in("r8") len as i64,
            in("r9") 0i64, // flags = 0
            lateout("rax") res,
            options(nostack),
        );
        res
    };
    if result < 0 {
        Err(io::Error::from_raw_os_error(-result as i32))
    } else {
        Ok(result as usize)
    }
}

fn main() {
    println!("ok");
}
EOF
